from flask import Flask, request, redirect, url_for, render_template_string, session, jsonify
from dataclasses import dataclass, asdict, field
from typing import Dict, List, Optional
from datetime import datetime
import itertools
import os

app = Flask(__name__)
app.secret_key = os.environ.get('SECRET_KEY', 'dev-secret-key')

PRODUCTS = {}
ORDERS = {}
AUDIT_LOG = []
COUNTERS = {
    'product': itertools.count(1),
    'order': itertools.count(1001),
}

@dataclass
class Product:
    id: int
    name: str
    description: str
    price: Optional[float]
    quantity: int
    category: str = 'General'
    active: bool = True
    stock_control: bool = True
    min_qty: int = 1
    max_qty: int = 10
    images: List[str] = field(default_factory=list)

    def purchasable(self):
        if not self.active:
            return False, 'Product is inactive.'
        if self.price is None or self.price <= 0:
            return False, 'Product price is missing or invalid.'
        if self.stock_control and self.quantity <= 0:
            return False, 'Product is out of stock.'
        return True, ''

@dataclass
class Order:
    id: int
    items: List[dict]
    total: float
    status: str = 'pending'
    payment_status: str = 'unpaid'
    created_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())


def log_action(actor, action, before=None, after=None):
    AUDIT_LOG.append({
        'who': actor,
        'what': action,
        'when': datetime.utcnow().isoformat(),
        'before': before,
        'after': after,
    })


def get_cart():
    return session.setdefault('cart', {})


def cart_items():
    cart = get_cart()
    items = []
    for pid_str, qty in cart.items():
        product = PRODUCTS.get(int(pid_str))
        if product:
            items.append((product, qty))
    return items


def cart_validation():
    issues = []
    for product, qty in cart_items():
        ok, msg = product.purchasable()
        if not ok:
            issues.append(f'{product.name}: {msg}')
        if qty < product.min_qty or qty > product.max_qty:
            issues.append(f'{product.name}: quantity must be between {product.min_qty} and {product.max_qty}.')
        if product.stock_control and qty > product.quantity:
            issues.append(f'{product.name}: insufficient stock.')
    return issues

HOME_TMPL = '''
<h1>GAMMA-J Web Store</h1>
<p><a href="/store">Storefront</a> | <a href="/cart">Cart</a> | <a href="/admin">Admin</a> | <a href="/orders">Orders</a></p>
'''

STORE_TMPL = '''
<h2>Storefront</h2>
{% for p in products %}
  <div>
    <strong>{{p.name}}</strong> - ${{'%.2f'|format(p.price or 0)}}
    <div>{{p.description}}</div>
    <div>Category: {{p.category}} | Stock: {{p.quantity}}</div>
    {% if p.purchasable[0] %}
      <form method="post" action="/cart/add/{{p.id}}"><button>Add to cart</button></form>
    {% else %}
      <p>Unavailable: {{p.purchasable[1]}}</p>
    {% endif %}
  </div><hr>
{% endfor %}
'''

@app.route('/')
def home():
    return render_template_string(HOME_TMPL)

@app.route('/store')
def store():
    products = []
    for p in PRODUCTS.values():
        products.append(type('P', (), {**asdict(p), 'purchasable': p.purchasable()}))
    return render_template_string(STORE_TMPL, products=products)

@app.route('/admin')
def admin_index():
    return jsonify({'products': [asdict(p) for p in PRODUCTS.values()], 'orders': [asdict(o) for o in ORDERS.values()], 'audit_log': AUDIT_LOG})

@app.route('/admin/products', methods=['POST'])
def admin_add_product():
    data = request.form or request.json or {}
    try:
        price = data.get('price')
        price = None if price in (None, '', 'null') else float(price)
        quantity = int(data.get('quantity', 0))
        product = Product(
            id=next(COUNTERS['product']),
            name=data['name'],
            description=data.get('description', ''),
            price=price,
            quantity=quantity,
            category=data.get('category', 'General'),
            active=str(data.get('active', 'true')).lower() != 'false',
            stock_control=str(data.get('stock_control', 'true')).lower() != 'false',
        )
    except Exception as e:
        return jsonify({'error': f'Invalid product data: {e}'}), 400
    PRODUCTS[product.id] = product
    log_action('staff', 'add_product', None, asdict(product))
    return jsonify(asdict(product)), 201

@app.route('/admin/products/<int:pid>', methods=['PUT'])
def admin_update_product(pid):
    product = PRODUCTS.get(pid)
    if not product:
        return jsonify({'error': 'Not found'}), 404
    before = asdict(product)
    data = request.form or request.json or {}
    if 'name' in data: product.name = data['name']
    if 'description' in data: product.description = data['description']
    if 'price' in data:
        product.price = None if data['price'] in (None, '', 'null') else float(data['price'])
    if 'quantity' in data: product.quantity = int(data['quantity'])
    if 'category' in data: product.category = data['category']
    if 'active' in data: product.active = str(data['active']).lower() != 'false'
    if 'stock_control' in data: product.stock_control = str(data['stock_control']).lower() != 'false'
    log_action('staff', 'update_product', before, asdict(product))
    return jsonify(asdict(product))

@app.route('/cart')
def cart_view():
    issues = cart_validation()
    lines = [f"{p.name} x {qty} = ${p.price * qty:.2f}" for p, qty in cart_items()]
    return jsonify({'cart': lines, 'issues': issues})

@app.route('/cart/add/<int:pid>', methods=['POST'])
def cart_add(pid):
    product = PRODUCTS.get(pid)
    if not product:
        return jsonify({'error': 'Product not found'}), 404
    ok, msg = product.purchasable()
    if not ok:
        return jsonify({'error': msg}), 400
    qty = int(request.form.get('qty', 1) or 1)
    cart = get_cart()
    new_qty = cart.get(str(pid), 0) + qty
    if new_qty > product.max_qty:
        return jsonify({'error': f'{product.name}: quantity exceeds maximum of {product.max_qty}'}), 400
    cart[str(pid)] = new_qty
    session['cart'] = cart
    return redirect(url_for('cart_view'))

@app.route('/checkout', methods=['POST'])
def checkout():
    issues = cart_validation()
    if issues:
        return jsonify({'error': 'Cart has issues', 'issues': issues}), 400
    items = []
    total = 0.0
    for product, qty in cart_items():
        items.append({'product_id': product.id, 'name': product.name, 'qty': qty, 'price': product.price})
        total += product.price * qty
    order = Order(id=next(COUNTERS['order']), items=items, total=total)
    ORDERS[order.id] = order
    for product, qty in cart_items():
        if product.stock_control:
            product.quantity -= qty
    session['cart'] = {}
    order.payment_status = 'paid'
    order.status = 'confirmed'
    return jsonify({'order_number': order.id, 'items': items, 'total': total, 'payment_status': order.payment_status, 'status': order.status}), 200

@app.route('/orders')
def orders():
    return jsonify([asdict(o) for o in ORDERS.values()])

@app.route('/orders/<int:oid>')
def order_detail(oid):
    order = ORDERS.get(oid)
    if not order:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(asdict(order))

@app.route('/health')
def health():
    return jsonify({'ok': True})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 8000)), debug=True)
EOF

