import app


def setup_function(_):
    app.PRODUCTS.clear()
    app.ORDERS.clear()
    app.AUDIT_LOG.clear()
    app.COUNTERS['product'] = __import__('itertools').count(1)
    app.COUNTERS['order'] = __import__('itertools').count(1001)


def test_add_and_browse_product():
    client = app.app.test_client()
    resp = client.post('/admin/products', json={'name': 'Widget', 'description': 'A thing', 'price': 9.99, 'quantity': 5})
    assert resp.status_code == 201
    resp = client.get('/store')
    assert b'Widget' in resp.data


def test_unavailable_product_blocks_add_to_cart():
    client = app.app.test_client()
    client.post('/admin/products', json={'name': 'Sold out', 'description': '', 'price': 10, 'quantity': 0})
    resp = client.post('/cart/add/1')
    assert resp.status_code == 400
    assert b'out of stock' in resp.data


def test_checkout_creates_order_and_reduces_stock():
    client = app.app.test_client()
    client.post('/admin/products', json={'name': 'Widget', 'description': 'A thing', 'price': 9.99, 'quantity': 5})
    client.post('/cart/add/1')
    resp = client.post('/checkout')
    assert resp.status_code == 200
    data = resp.get_json()
    assert data['status'] == 'confirmed'
    assert data['payment_status'] == 'paid'
    assert app.PRODUCTS[1].quantity == 4


def test_cart_quantity_limit():
    client = app.app.test_client()
    client.post('/admin/products', json={'name': 'Widget', 'description': 'A thing', 'price': 9.99, 'quantity': 100, 'max_qty': 2})
    resp = client.post('/cart/add/1', data={'qty': 11})
    assert resp.status_code == 400
EOF

