    order = Order(id=next(COUNTERS['order']), items=items, total=total)
    ORDERS[order.id] = order
    for product, qty in cart_items():
        if product.stock_control:
            product.quantity -= qty
    session['cart'] = {}
    order.payment_status = 'paid'
    order.status = 'confirmed'
    return jsonify({'order_number': order.id, 'items': items, 'total': total, 'payment_status': order.payment_status, 'status': order.status}), 200

@app.route('/orders')
def orders():
    return jsonify([asdict(o) for o in ORDERS.values()])

@app.route('/orders/<int:oid>')
